```python
def find_anagrams(s: str, p: str) -> list[int]:
    if len(s) < len(p):
        return []

    p_counts = [0] * 26
    s_counts = [0] * 26
    k = len(p)

    for char in p:
        p_counts[ord(char) - ord('a')] += 1
    for i in range(k):
        s_counts[ord(s[i]) - ord('a')] += 1

    results = []
    if s_counts == p_counts:
        results.append(0)

    for i in range(k, len(s)):
        s_counts[ord(s[i]) - ord('a')] += 1
        s_counts[ord(s[i - k]) - ord('a')] -= 1
        if s_counts == p_counts:
            results.append(i - k + 1)

    return results
```

