# Number of islands via BFS component exploration
def num_islands_bfs(grid):
    if not grid: return 0
    R, C = len(grid), len(grid[0])
    visited = set()
    islands = 0
    for r in range(R):
        for c in range(C):
            if grid[r][c] == '1' and (r, c) not in visited:
                islands += 1
                q = deque([(r, c)])
                visited.add((r, c))
                while q:
                    cr, cc = q.popleft()
                    for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == '1' and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            q.append((nr, nc))
    return islands

