import functools

def wrap_alpha(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        return f'[ALPHA {func(*args, **kwargs)} ALPHA]'
    return wrapper

def wrap_beta(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        return f'(BETA {func(*args, **kwargs)} BETA)'
    return wrapper

@wrap_alpha
@wrap_beta
def message():
    return 'payload'

print(message())

import functools

def memoize(func):
    cache = {}
    @functools.wraps(func)
    def wrapper(*args):
        if args not in cache:
            cache[args] = func(*args)
        return cache[args]
    return wrapper

@memoize
def square(n: int) -> int:
    return n * n

print(square(4), square(4))

def double_result(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs) * 2
    return wrapper

@double_result
def add(a: int, b: int) -> int:
    return a + b

