SELECT name, salary,
    CASE 
        WHEN salary >= 80000 THEN 'Senior / Lead'
        WHEN salary >= 45000 THEN 'Mid-Level'
        ELSE 'Junior'
    END AS tier
FROM employees;

SELECT day, amount, SUM(amount) OVER () AS grand_total
FROM sales
ORDER BY day;

WITH ranked AS (
  SELECT employee_id, department, salary,
    ROW_NUMBER() OVER (PARTITION BY department ORDER BY salary DESC, employee_id) AS rn
  FROM employees
)
SELECT employee_id, department, salary FROM ranked WHERE rn = 1;
